node -e '
const c = require("crypto");
const k = process.env.PAYMENTS_KEY;
if (!k) { console.log("PAYMENTS_KEY: NOT SET in shell environment"); process.exit(0); }
const sha = c.createHash("sha256").update(k).digest("hex").slice(0,12);
console.log("set: yes");
console.log("length:", k.length);
console.log("sha256[:12]:", sha);
'

node --env-file=.env -e '
const c = require("crypto");
const k = process.env.PAYMENTS_KEY;
if (!k) { console.log("PAYMENTS_KEY: NOT SET after loading .env"); process.exit(0); }
const t = (re) => re.test(k);
console.log("set: yes");
console.log("length:", k.length);
console.log("prefix pk_:", t(/^pk_/), "| prefix sk_:", t(/^sk_/), "| other prefix:", !t(/^(pk_|sk_)/));
console.log("test-mode marker:", t(/^(pk|sk)_test_/), "| live-mode marker:", t(/^(pk|sk)_live_/));
console.log("leading/trailing whitespace:", t(/^\s|\s$/));
console.log("any whitespace inside:", t(/\s/));
console.log("contains quote chars:", k.includes(String.fromCharCode(34)) || k.includes(String.fromCharCode(39)));
console.log("non-printable/non-ascii chars:", t(/[^\x21-\x7e]/));
console.log("sha256[:12]:", c.createHash("sha256").update(k).digest("hex").slice(0,12));
'
